import { AsyncLocalStorage } from 'node:async_hooks';
const storage = new AsyncLocalStorage();
function check(expected) { if (storage.getStore() !== expected) throw new Error('wrong context: ' + storage.getStore() + ' expected ' + expected); }
let release; const barrier = new Promise(resolve => { release = resolve; });
const first = storage.run('first', async () => { check('first'); await barrier; check('first'); await Promise.resolve(); check('first'); return storage.getStore(); });
check(undefined);
const second = storage.run('second', async () => { check('second'); release(); await Promise.resolve(); check('second'); return storage.getStore(); });
check(undefined);
const result = await Promise.all([first, second]); check(undefined);
console.log(JSON.stringify(result));

