import { AsyncLocalStorage } from 'node:async_hooks';
const a = new AsyncLocalStorage(); const b = new AsyncLocalStorage(); const reason = new Error('identity');
const result = await a.run({ id: 7 }, async () => { const parent = a.getStore();
try { a.run({ id: 8 }, () => { if (a.getStore().id !== 8) throw new Error('nested'); throw reason; }); } catch (error) { if (error !== reason) throw error; }
if (a.getStore() !== parent) throw new Error('not restored');
return b.run(9, async () => { await Promise.resolve(); if (a.getStore() !== parent || b.getStore() !== 9) throw new Error('cross storage'); return [parent.id, b.getStore()]; }); });
if (a.getStore() !== undefined || b.getStore() !== undefined) throw new Error('leak'); console.log(JSON.stringify(result));

