import { AsyncLocalStorage } from 'node:async_hooks';
import process from 'node:process';
const storage = new AsyncLocalStorage();
const result = await storage.run('registered', () => Promise.all([
new Promise(resolve => queueMicrotask(() => resolve(storage.getStore()))),
new Promise(resolve => process.nextTick(() => resolve(storage.getStore()))),
Promise.resolve().then(() => storage.getStore())]));
if (JSON.stringify(result) !== '["registered","registered","registered"]' || storage.getStore() !== undefined) throw new Error('wrong callback capture'); console.log(JSON.stringify(result));

