import { createGzip, gunzipSync } from 'zlib';
import { Buffer } from 'node:buffer';
const input = Buffer.from('actual gzip data: ' + 'abc123'.repeat(1000));
const gzip = createGzip(); const chunks = [];
const output = await new Promise((resolve, reject) => { gzip.on('data', chunk => chunks.push(chunk)); gzip.on('end', () => resolve(Buffer.concat(chunks))); gzip.on('error', reject); gzip.write(input.subarray(0, 100)); gzip.end(input.subarray(100)); });
if (output[0] !== 31 || output[1] !== 139 || output.length >= input.length || gunzipSync(output).toString() !== input.toString()) throw new Error('invalid gzip data'); console.log('OK real gzip round trip');

